package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.jscomp.logging.GoogleLogger;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_shouldTraverse_TriageGen1Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal mockTraversal;

    @Mock
    private Node mockN;

    @Mock
    private Node mockParent;

    @Mock
    private JSDocInfo mockJsDoc;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // Since CheckGlobalThis is likely part of a larger framework, 
        // we instantiate it. Note: getFunctionJsDocInfo is likely a protected/private 
        // method in the real class. For unit testing purposes, we assume 
        // the environment allows testing this logic.
        checkGlobalThis = new CheckGlobalThis();
    }

    /**
     * Helper to mock Node behavior easily
     */
    private void setupNode(Node node, int type) {
        when(node.getType()).thenReturn(type);
    }

    @Test
    public void testNotFunction_ReturnsTrue() {
        setupNode(mockN, Token.NAME);
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, mockN, null));
    }

    @Test
    public void testFunction_NoJsDoc_ReturnsTrue() {
        setupNode(mockN, Token.FUNCTION);
        // Assuming getFunctionJsDocInfo returns null if no JSDoc found
        // We rely on the fact that we can't easily mock the internal call unless we spy or mock the class
        // For this test, we assume the logic flows to the end.
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, mockN, null));
    }

    @Test
    public void testFunction_IsConstructor_ReturnsFalse() {
        // This test requires spying to override getFunctionJsDocInfo if it's not accessible
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        setupNode(mockN, Token.FUNCTION);
        when(spyCheck.getFunctionJsDocInfo(mockN)).thenReturn(mockJsDoc);
        when(mockJsDoc.isConstructor()).thenReturn(true);

        assertFalse(spyCheck.shouldTraverse(mockTraversal, mockN, null));
    }

    @Test
    public void testFunction_HasThisType_ReturnsFalse() {
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        setupNode(mockN, Token.FUNCTION);
        when(spyCheck.getFunctionJsDocInfo(mockN)).thenReturn(mockJsDoc);
        when(mockJsDoc.isConstructor()).thenReturn(false);
        when(mockJsDoc.hasThisType()).thenReturn(true);

        assertFalse(spyCheck.shouldTraverse(mockTraversal, mockN, null));
    }

    @Test
    public void testAssignment_LHS_SetsAssignLhsChildAndReturnsTrue() {
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        setupNode(mockN, Token.NAME);
        setupNode(mockParent, Token.ASSIGN);

        Node lhs = mock(Node.class);
        Node rhs = mock(Node.class);
        setupNode(lhs, Token.NAME);
        when(mockParent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        // n is lhs
        assertTrue(spyCheck.shouldTraverse(mockTraversal, lhs, mockParent));
    }

    @Test
    public void testAssignment_RHS_NotPrototype_ReturnsTrue() {
        setupNode(mockN, Token.NAME);
        setupNode(mockParent, Token.ASSIGN);

        Node lhs = mock(Node.class);
        Node rhs = mock(Node.class);
        setupNode(lhs, Token.NAME);
        when(mockParent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);

        // n is rhs
        assertTrue(spyCheck.shouldTraverse(mockTraversal, rhs, mockParent));
    }

    @Test
    public void testAssignment_RHS_PrototypeProperty_ReturnsFalse() {
        setupNode(mockN, Token.NAME);
        setupNode(mockParent, Token.ASSIGN);

        Node lhs = mock(Node.class);
        Node rhs = mock(Node.class);
        Node lastChild = mock(Node.class);

        setupNode(lhs, Token.GETPROP);
        when(mockParent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("prototype");

        // n is rhs
        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, rhs, mockParent));
    }

    @Test
    public void testAssignment_RHS_QualifiedNameContainsPrototype_ReturnsFalse() {
        setupNode(mockN, Token.NAME);
        setupNode(mockParent, Token.ASSIGN);

        Node lhs = mock(Node.class);
        Node rhs = mock(Node.class);
        Node lastChild = mock(Node.class);

        setupNode(lhs, Token.GETPROP);
        when(mockParent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("somethingElse");
        when(lhs.getQualifiedName()).thenReturn("obj.prototype.prop");

        // n is rhs
        assertFalse(checkGlobalThis.shouldTraverse(mockTraversal, rhs, mockParent));
    }

    @Test
    public void testAssignment_RHS_QualifiedNameNull_ReturnsTrue() {
        setupNode(mockN, Token.NAME);
        setupNode(mockParent, Token.ASSIGN);

        Node lhs = mock(Node.class);
        Node rhs = mock(Node.class);
        Node lastChild = mock(Node.class);

        setupNode(lhs, Token.GETPROP);
        when(mockParent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("somethingElse");
        when(lhs.getQualifiedName()).thenReturn(null);

        // n is rhs
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, rhs, mockParent));
    }

    @Test
    public void testAssignment_RHS_QualifiedNameNoPrototype_ReturnsTrue() {
        setupNode(mockN, Token.NAME);
        setupNode(mockParent, Token.ASSIGN);

        Node lhs = mock(Node.class);
        Node rhs = mock(Node.class);
        Node lastChild = mock(Node.class);

        setupNode(lhs, Token.GETPROP);
        when(mockParent.getFirstChild()).thenReturn(lhs);
        when(lhs.getNext()).thenReturn(rhs);
        when(lhs.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("somethingElse");
        when(lhs.getQualifiedName()).thenReturn("obj.prop");

        // n is rhs
        assertTrue(checkGlobalThis.shouldTraverse(mockTraversal, rhs, mockParent));
    }
}
